20260813000000	{"-- Muthoy cloud mirror. SQLite remains the mobile source of truth.\n-- Client timestamps are preserved for Beta last-write-wins; no updated_at trigger.\n\ncreate table shops (\n  id uuid primary key,\n  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),\n  is_deleted boolean not null default false, deleted_at timestamptz, deleted_by uuid,\n  owner_id uuid not null, name text not null, name_en text, phone text not null,\n  latitude double precision, longitude double precision, thana text, district text,\n  location_captured_at timestamptz, plan text not null default 'free', trial_ends_at timestamptz\n)","create index shops_owner_idx on shops(owner_id)","-- Independent first-claim-wins registry. Claims precede the cloud shops row.\ncreate table shop_claims (\n  shop_id uuid primary key,\n  claimed_by_user_id uuid not null unique,\n  claimed_at timestamptz not null default now()\n)","alter table shop_claims enable row level security","revoke all on table shop_claims from public, anon, authenticated","grant select, insert on table shop_claims to service_role","create table subscriptions (\n  id uuid primary key,\n  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),\n  is_deleted boolean not null default false, deleted_at timestamptz, deleted_by uuid,\n  shop_id uuid not null references shops(id) on delete cascade,\n  plan text not null, status text not null default 'trialing', starts_at timestamptz not null,\n  ends_at timestamptz, next_billing_at timestamptz, payment_provider text, payment_reference text\n)","create index subscriptions_shop_idx on subscriptions(shop_id)","create index subscriptions_shop_status_idx on subscriptions(shop_id, status)","create table roles (\n  id uuid primary key,\n  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),\n  is_deleted boolean not null default false, deleted_at timestamptz, deleted_by uuid,\n  shop_id uuid not null references shops(id) on delete cascade,\n  name text not null, is_system boolean not null default true\n)","create index roles_shop_idx on roles(shop_id)","create table permissions (\n  id uuid primary key,\n  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),\n  is_deleted boolean not null default false, deleted_at timestamptz, deleted_by uuid,\n  role_id uuid not null references roles(id) on delete restrict,\n  key text not null, allowed boolean not null default false\n)","create index permissions_role_idx on permissions(role_id)","create table users (\n  id uuid primary key,\n  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),\n  is_deleted boolean not null default false, deleted_at timestamptz, deleted_by uuid,\n  shop_id uuid not null references shops(id) on delete cascade,\n  name text not null, phone text, pin_hash text not null, pin_set_at timestamptz,\n  role_id uuid not null references roles(id) on delete restrict,\n  is_active boolean not null default true\n)","create index users_shop_idx on users(shop_id)","create index users_shop_active_idx on users(shop_id, is_active)","create table medicines (\n  id uuid primary key,\n  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),\n  is_deleted boolean not null default false, deleted_at timestamptz, deleted_by uuid,\n  shop_id uuid not null references shops(id) on delete cascade,\n  name text not null, generic text, manufacturer text, type text, strength text, category text,\n  unit_of_measure text not null default 'piece', requires_prescription boolean not null default false,\n  barcode text, threshold integer not null default 20\n)","create index medicines_shop_idx on medicines(shop_id)","create index medicines_barcode_idx on medicines(barcode)","create table batches (\n  id uuid primary key,\n  created_at timestamptz not null default now(), updated_a